import sys; from pathlib import Path; sys.path.insert(0, str(Path(__file__).resolve().parents[2])); from common.testing.coverage import merge_lcov as ml; LCOV_A = 'SF:/repo/src/a.py\nDA:1,1\nDA:2,0\nDA:3,2\nend_of_record\nSF:/repo/src/b.py\nDA:10,0\nDA:11,0\nend_of_record\n'; LCOV_B = 'SF:/repo/src/a.py\nDA:1,0\nDA:2,3\nDA:3,0\nend_of_record\nSF:/repo/src/c.py\nDA:5,1\nend_of_record\n'
class TestParseLcovToRecords:
    def test_parses_single_file(self, tmp_path): f = tmp_path / 'a.lcov'; f.write_text(LCOV_A); records = ml.parse_lcov_to_records(f); assert '/repo/src/a.py' in records; assert records['/repo/src/a.py']['lines'] == {1: 1, 2: 0, 3: 2}; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _m1_f = _m1_tmp / 'a.lcov'; _m1_f.write_text(LCOV_A); _m1_records = ml.parse_lcov_to_records(_m1_f); assert len(_m1_records) == 2; assert '/repo/src/b.py' in _m1_records; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_content = 'SF:/repo/dup.py\nDA:1,2\nDA:1,5\nend_of_record\n'; _m2_f = _m2_tmp / 'dup.lcov'; _m2_f.write_text(_m2_content); _m2_records = ml.parse_lcov_to_records(_m2_f); assert _m2_records['/repo/dup.py']['lines'][1] == 5; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _m3_content = 'SF:/repo/x.py\nDA:bad,line\nDA:1,1\nend_of_record\n'; _m3_f = _m3_tmp / 'bad.lcov'; _m3_f.write_text(_m3_content); _m3_records = ml.parse_lcov_to_records(_m3_f); assert _m3_records['/repo/x.py']['lines'].get(1) == 1; _m4_tmp = tmp_path / '_m4'; _m4_tmp.mkdir(exist_ok=True); _m4_content = 'SF:/repo/x.py\nDA:1\nDA:2,3\nend_of_record\n'; _m4_f = _m4_tmp / 'short.lcov'; _m4_f.write_text(_m4_content); _m4_records = ml.parse_lcov_to_records(_m4_f); assert _m4_records['/repo/x.py']['lines'] == {2: 3}; _m5_tmp = tmp_path / '_m5'; _m5_tmp.mkdir(exist_ok=True); _m5_content = 'SF:/repo/z.py\nDA:1,1\n'; _m5_f = _m5_tmp / 'partial.lcov'; _m5_f.write_text(_m5_content); _m5_records = ml.parse_lcov_to_records(_m5_f); assert '/repo/z.py' in _m5_records; assert _m5_records['/repo/z.py']['lines'][1] == 1; _m6_tmp = tmp_path / '_m6'; _m6_tmp.mkdir(exist_ok=True); _m6_content = 'SF:/repo/dup.py\nDA:1,0\nend_of_record\nSF:/repo/dup.py\nDA:1,4\n'; _m6_f = _m6_tmp / 'duplicate-partial.lcov'; _m6_f.write_text(_m6_content); _m6_records = ml.parse_lcov_to_records(_m6_f); assert _m6_records['/repo/dup.py']['lines'] == {1: 4}; _m7_tmp = tmp_path / '_m7'; _m7_tmp.mkdir(exist_ok=True); _m7_f = _m7_tmp / 'empty.lcov'; _m7_f.write_text(''); _m7_records = ml.parse_lcov_to_records(_m7_f); assert _m7_records == {}
class TestMergeRecords:
    def test_union_of_different_files(self, tmp_path): f_a = tmp_path / 'a.lcov'; f_a.write_text(LCOV_A); f_b = tmp_path / 'b.lcov'; f_b.write_text(LCOV_B); r_a = ml.parse_lcov_to_records(f_a); r_b = ml.parse_lcov_to_records(f_b); merged = ml.merge_records([r_a, r_b]); assert '/repo/src/a.py' in merged; assert '/repo/src/b.py' in merged; assert '/repo/src/c.py' in merged; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _m1_f_a = _m1_tmp / 'a.lcov'; _m1_f_a.write_text(LCOV_A); _m1_f_b = _m1_tmp / 'b.lcov'; _m1_f_b.write_text(LCOV_B); _m1_r_a = ml.parse_lcov_to_records(_m1_f_a); _m1_r_b = ml.parse_lcov_to_records(_m1_f_b); _m1_merged = ml.merge_records([_m1_r_a, _m1_r_b]); _m1_lines = _m1_merged['/repo/src/a.py']['lines']; assert _m1_lines[1] == 1; assert _m1_lines[2] == 3; assert _m1_lines[3] == 2; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_f = _m2_tmp / 'a.lcov'; _m2_f.write_text(LCOV_A); _m2_r = ml.parse_lcov_to_records(_m2_f); _m2_merged = ml.merge_records([_m2_r]); assert _m2_merged['/repo/src/a.py']['lines'] == {1: 1, 2: 0, 3: 2}
    def test_empty_list(self): assert ml.merge_records([]) == {}
class TestWriteLcov:
    def test_writes_sf_da_lf_lh(self, tmp_path): records = {'/repo/src/x.py': {'lines': {1: 1, 2: 0, 3: 3}}}; out = tmp_path / 'out.lcov'; ml.write_lcov(records, out); content = out.read_text(); assert 'SF:/repo/src/x.py' in content; assert 'DA:1,1' in content; assert 'DA:2,0' in content; assert 'DA:3,3' in content; assert 'LF:3' in content; assert 'LH:2' in content; assert 'end_of_record' in content; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _m1_records = {'/repo/src/y.py': {'lines': {1: 0, 2: 0, 3: 0}}}; _m1_out = _m1_tmp / 'out.lcov'; ml.write_lcov(_m1_records, _m1_out); _m1_content = _m1_out.read_text(); assert 'LH:0' in _m1_content; assert 'LF:3' in _m1_content; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_records = {'/z.py': {'lines': {1: 1}}, '/a.py': {'lines': {1: 1}}}; _m2_out = _m2_tmp / 'sorted.lcov'; ml.write_lcov(_m2_records, _m2_out); _m2_content = _m2_out.read_text(); assert _m2_content.index('SF:/a.py') < _m2_content.index('SF:/z.py'); _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _m3_f_a = _m3_tmp / 'a.lcov'; _m3_f_a.write_text(LCOV_A); _m3_records_in = ml.parse_lcov_to_records(_m3_f_a); _m3_out = _m3_tmp / 'out.lcov'; ml.write_lcov(_m3_records_in, _m3_out); _m3_records_out = ml.parse_lcov_to_records(_m3_out); assert all((_m3_sf in _m3_records_out and all((_m3_records_out[_m3_sf]['lines'][_m3_line_num] == _m3_hit for _m3_line_num, _m3_hit in _m3_rec['lines'].items())) for _m3_sf, _m3_rec in _m3_records_in.items()))
class TestMain:
    def test_main_merges_two_files(self, tmp_path): f_a = tmp_path / 'a.lcov'; f_a.write_text(LCOV_A); f_b = tmp_path / 'b.lcov'; f_b.write_text(LCOV_B); out = tmp_path / 'merged.lcov'; assert ml.main([str(out), str(f_a), str(f_b)]) == 0; assert out.exists(); records = ml.parse_lcov_to_records(out); assert len(records) == 3
    def test_main_warns_on_missing_input(self, tmp_path, capsys): out = tmp_path / 'merged.lcov'; missing = tmp_path / 'nonexistent.lcov'; assert ml.main([str(out), str(missing)]) == 0; captured = capsys.readouterr(); assert 'not found' in captured.out or 'Warning' in captured.out; assert out.exists(); assert ml.parse_lcov_to_records(out) == {}
    def test_main_exits_on_no_args(self): assert ml.main([]) == 2
class TestSharedLcovHelper:
    def test_is_branch_record(self) -> None: from common.testing.coverage import lcov; assert lcov.is_branch_record('BRDA:1,0,0,1') is True; assert lcov.is_branch_record('BRF:2') is True; assert lcov.is_branch_record('BRH:1') is True; assert lcov.is_branch_record('DA:1,1') is False; assert lcov.is_branch_record('SF:src/main.py') is False
    def test_parse_line_hits_accumulate_sum(self, tmp_path: Path) -> None: from common.testing.coverage import lcov; f = tmp_path / 'shard.lcov'; f.write_text('SF:src/app.py\nDA:1,2\nDA:2,0\nend_of_record\nSF:src/app.py\nDA:1,3\nend_of_record\n'); hits = lcov.parse_line_hits(f, accumulate='sum'); assert hits['src/app.py'][1] == 5; assert hits['src/app.py'][2] == 0; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); from common.testing.coverage import lcov; _m1_f = _m1_tmp / 'summary.lcov'; _m1_f.write_text('SF:src/x.py\nLH:5\nLF:10\nend_of_record\n'); _m1_summaries = lcov.parse_lcov_summaries(_m1_f); assert _m1_summaries['src/x.py'] == {'covered_lines': 5, 'total_lines': 10}
